function showIntro3(){introBg.events.onInputUp.remove(showIntro3,this)
game.intro.bubble.kill();game.intro.introText.destroy();game.intro.bubble=game.add.sprite(470,160,'bubble3');game.intro.bubble.anchor.x=game.intro.bubble.anchor.y=0.5;var intro1Str=getXmlString('introText3');game.intro.introText=createSpeechText(intro1Str);game.intro.introText.wordWrapWidth=300;game.intro.introText.wordWrap=true;introBg.events.onInputUp.add(showIntro4,this)
matchPos(game.intro.introText,game.intro.bubble);}
function showIntro4(){introBg.events.onInputUp.remove(showIntro4,this)
game.intro.bubble.kill();game.intro.introText.destroy();game.intro.bubble=game.add.sprite(130,340,'bubble4');game.intro.bubble.anchor.x=game.intro.bubble.anchor.y=0.5;var intro1Str=getXmlString('introText4');game.intro.introText=createSpeechText(intro1Str);game.intro.introText.wordWrapWidth=300;game.intro.introText.wordWrap=true;introBg.events.onInputUp.add(showIntro5,this)
matchPos(game.intro.introText,game.intro.bubble);}
function showIntro5(){introBg.events.onInputUp.remove(showIntro5,this)
game.intro.bubble.kill();game.intro.introText.destroy();game.add.sprite(0,0,'introBg2');game.intro.bubble=game.add.sprite(GAME_WIDTH/2,50,'bubble5');game.intro.bubble.anchor.x=game.intro.bubble.anchor.y=0.5;var intro1Str=getXmlString('introText5');game.intro.introText=createSpeechText(intro1Str);game.intro.introText.wordWrapWidth=400;game.intro.introText.wordWrap=true;game.intro.introText.fontSize=20;introBg.events.onInputUp.add(endIntro,this)
matchPos(game.intro.introText,game.intro.bubble);game.intro.introText.y-=20;}
function endIntro(){game.currentLevelId=0;game.fromTutorial=true;game.music.stop();game.state.start('inGame');}
function createMapText(str){var text=game.add.text(0,0,str);text.anchor.set(0.5);text.align='center';text.font='Conv_Joe_Font';text.fontSize=14;text.fill='#000000';return text;}
function createButtonText(str,sprite){var text=game.add.text(0,0,str);text.anchor.set(0.5);text.align='center';text.font='Conv_PlacardGFMod-Bold';text.fontSize=30;text.stroke='#144742';text.strokeThickness=6;text.fill='#2C988C';return text;}
function createHeaderText(str,sprite){var text=game.add.text(0,0,str);text.anchor.set(0.5);text.align='center';text.font='Conv_PlacardGFMod-Bold';text.fontSize=24;text.fill='#000000';return text;}
function createSpeechText(str){var text=game.add.text(0,0,str);text.anchor.set(0.5);text.align='center';text.font='Conv_Joe_Font';text.fontSize=14;text.fill='#000000';return text;}
function getXmlString(key){key=key.toUpperCase();var str=xml.querySelector(key).textContent;return str;}
function matchPos(a,b){a.x=b.x;a.y=b.y;}
function scaleDownBtn(btn){}
function findPointer(btn){if(game.input.pointer1.targetObject===btn){return game.input.pointer1;}else{return game.input.pointer2;}}
function setRollOverButton(btn){btn.setFrames('WoodBtn0001','WoodBtn0000');btn.onOverSound=sfx;btn.onOverSoundMarker='rollOver';}
function setRollOverButtonLarge(btn){btn.setFrames('WoodBtnLarge0001','WoodBtnLarge0000');}
function removeUiStack(){for(var i=0;i<game.uiStack.length;i++){var sprite=game.uiStack[i];sprite.kill();}
game.uiStack=[];for(var i=0;i<game.textStack.length;i++){var tx=game.textStack[i];tx.destroy();tx=null;}
game.textStack=[];}
function forEachType(func,group,type){for(var i=0;i<group.total;i++){var obj=group.getAt(i);if(obj.key===type){func(obj);}}}
function setSounds(){sfx=game.add.audio('sfx');sfx.allowMultiple=true;sfx.addMarker('rollOver',0,.59);sfx.addMarker('land',.6,.375);sfx.addMarker('star',.9,1.9);sfx.addMarker('jump',2.9,.27);sfx.addMarker('levelComplete',3.78,2.11);sfx.addMarker('vortex',5.8,3);sfx.addMarker('hurt1',8.9,.66);sfx.addMarker('hurt2',9.6,.61);}
function showJumpRipple(touch){game.level.jumpRipple.x=touch.x;game.level.jumpRipple.y=touch.y;game.level.jumpRipple.visible=true;game.level.jumpRipple.animations.play('ripple',30,false);}
function gameResized(e){}
function enterIncorrectOrientation(e){document.getElementById('rotate').style.display='block';}
function leaveIncorrectOrientation(e){document.getElementById('rotate').style.display='none';}
function onLeaveGame(){}
function onRollOverLevelBtn(btn){btn.tint=0xc59558;btn.scale.x=btn.scale.y=1.2;}
function onRollOutLevelBtn(btn){btn.tint=0xFFFFFF;btn.scale.x=btn.scale.y=1;}
function playdomTrack(eventStr,msgStr){eventStr=eventStr.toLowerCase();var playdomUrl='http://log.data.disney.com/cp';var dataObj={app:APP_ID,user_id:getUDID(),app_locale:APP_LOCALE,tag:"game_action",transaction_id:getSession(),browser_id:getUDID(),network:'bd',view_network:'bd',context:'game_action='+eventStr,message:msgStr};$.ajax({type:"GET",datatype:"json",url:playdomUrl,data:dataObj,success:function(response){html(response);}});return false;}
function playdomTrackDevice(){var playdomUrl='http://log.data.disney.com/cp';var dataObj={app:APP_ID,user_id:getUDID(),app_locale:APP_LOCALE,tag:"device_info",transaction_id:getSession(),browser_id:getUDID(),network:'bd',view_network:'bd',os_version:getOS(),machine:navigator.userAgent};$.ajax({type:"GET",datatype:"json",url:playdomUrl,data:dataObj,success:function(response){html(response);}});return false;}
function getOS(){if(game.device.windows){return "windows";}else if(game.device.macOS){return "macOS";}else if(game.device.iOS){return "iOS";}else if(game.device.android){return "android";}}
function getDevice(){if(game.device.windows){return windows}}
var UDID;function getUDID(){UDID=localStorage.getItem('UDID');if(UDID==""||UDID==null||UDID==undefined){var s="xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx";UDID=s.replace(/[xy]/g,function(c){var r=Math.random()*16|0,v=c=='x'?r:(r&0x3|0x8);return v.toString(16);});}
localStorage.setItem('UDID',UDID);return UDID;}
function getSession(){var session=localStorage.getItem('session');if(session==null||session==""||session==undefined){var s="xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx";session=s.replace(/[xy]/g,function(c){var r=Math.random()*16|0,v=c=='x'?r:(r&0x3|0x8);return v.toString(16);});}
localStorage.setItem('session',session);return session;}